// Keep the expanded ADHD guidance reachable from the existing wellbeing course too.
const focusOriginalCalmHome=calmHome;
calmHome=function(){focusOriginalCalmHome();const parent=document.querySelector('#calmGuide .sen-parent-copy');if(parent){const note=document.createElement('aside');note.className='focus-guide-link';note.innerHTML='<h3>More support for ADHD and ADD</h3><p>Explore 20 additional attention activities and our expanded parent guide: understanding inattentive ADHD, adapting tasks, using reminders, taking breaks, and the limits of computer training.</p><button class="secondary" id="focusFromCalm">ADHD / ADD guidance & games →</button>';parent.append(note);note.querySelector('button').onclick=()=>{focusHome();const guide=document.querySelector('#focusGuide');guide.open=true;guide.scrollIntoView();};}};
